  // id 撞车自动换号重试（2026-10-14 审查 P3）：id = 描述16字 + 毫秒末5位 base36，
  // 同毫秒同描述必撞——锁内查重命中就换一个新号再来（最多 3 次，仍撞则响亮拒）。
  let 节点 = null;
  for (let 尝试 = 0; 尝试 < 3 && !节点; 尝试 += 1) {
    const id = 尝试 === 0 ? 初始id : `task-${slugOf(input.描述, 'x')}-${(this.clock.ms() + 尝试).toString(36).slice(-5)}${尝试}`;
