        if (fold(rows).has(id)) {
          throw new InvalidBody(`节点 id 撞车：${id} 已存在（同毫秒同描述）。`, { detail: { id } });
        }
        this.#assertDependencies(依赖, id, fold(rows));
        return { ...事件, id };
      }));
    } catch (error) {
      if (error instanceof InvalidBody && /id 撞车/.test(error.message) && 尝试 < 2) continue;
      throw error;
    }
  }
