/**
 * 绑定实例（v2 口述收敛 2026-10-18 条目11）。
 *
 * 与 `reassign` 的分工（修前把两件事合成一件，这正是条目11 要纠的）：
 *  - **负责人 = 岗位名**：「这一岗」由谁负责，一岗多人 / 换人重跑都还成立；
 *  - **绑定 = 实例**：「此刻是谁在干」。`member_spawn` 起实例后绑它，**不改负责人**。
 * 判「全员已交」、`scopeOf` 的任务内全权、复核冲突排除，都按**已绑实例**算。
 *
 * 复核任务怎么指到被复核节点：沿用**既有载体 `依赖`**（`created` 事件就带，且有存在性 /
 * 环检查），不新造字段、不从任务书自由文本猜。于是一个「复核任务」= 依赖里含被复核节点、
 * 负责人是复核员岗、绑定是那个复核实例的节点。
 *
 * @param {string} id
 * @param {{ subject: object, 项目: string, 实例: string, 岗位: string }} spec
 */
async bind(id, spec) {
  if (!['Lead', '主权者'].includes(spec.subject?.kind)) {
    throw new Denied('任务图 · 绑定实例仅 Lead', `绑定是排兵动作（把实例绑到节点上）：${spec.subject?.kind ?? '未知'} 没有这只手。`, {
      requireAuthority: 'Lead',
      howToChange: '由 Lead 经 member_spawn（自动绑定）或显式绑定执行。',
    });
  }
  const 实例 = String(spec.实例 ?? '').trim();
  const 岗位 = String(spec.岗位 ?? '').trim();
  if (!实例) throw new InvalidBody('绑定需要「实例」：绑定的是具体哪一个会话实例。', { missing: ['实例'] });
  if (!岗位) throw new InvalidBody('绑定需要「岗位」：实例的权只来自岗位，绑定要记下它当时是哪一岗。', { missing: ['岗位'] });
  const node = await this.#require(id, spec.项目);
  this.#requireTransition(node, 'bind');
  await this.#checkWrite(id, node, spec);
  const 于 = this.clock.iso();
  const 绑定 = { 实例, 岗位, 于 };
  const { 节点 } = await this.#append(
    spec.项目,
    { kind: 'bound', id, 绑定 },
    spec.subject,
    '状态变更',
    (nodeInLock) => {
      if (!['待派发', '已派发'].includes(nodeInLock?.状态)) {
        throw new Denied('任务图 · 状态机', `节点 ${id} 在锁内已推进为 ${nodeInLock?.状态}，不能绑定（允许的状态：待派发 / 已派发）。`, {
          howToChange: '绑定要在排兵阶段：执行中起绑会把「谁在干」与已交的作业归属脱钩。',
        });
      }
      return { kind: 'bound', id, 绑定 };
    },
  );
  return 节点;
}

