/**
 * 复核署名的证据闸（v2 条目11 + 署名安全 H）。
 *
 * 两条都要，缺一条就是「账上有个名字」而已：
 *  ① **人真**：署名的复核者在身份档案里在岗、且岗位是复核员；
 *  ② **关联真**：存在一个「复核任务」——它的 `依赖` 含本次被复核节点（沿用既有载体，
 *     有存在性 / 环检查），且 `绑定` 里有这个实例。复核实例绑的是**它自己的复核节点**，
 *     不是被复核业务节点的负责人（两者混一处会与冲突排除自相矛盾）。
 *
 * 夹具不接 registry（直接 new TaskGraph）时退位——装配面 org.js 恒注入，见构造器注释。
 *
 * @param {string} 被复核节点
 * @param {string} 复核者id
 * @param {string} 项目
 */
async #assertReviewerEvidence(被复核节点, 复核者id, 项目) {
  if (!this.registry) return;
  const identity = await this.registry.identity();
  const member = identity?.members?.[复核者id];
  if (!member || member.status !== '在岗' || member.岗位 !== '复核员') {
    throw new Denied(
      '任务图 · 复核署名必须是真实在册在岗复核实例（v2 条目11/8）',
      `署名复核者 ${复核者id} 在身份档案里${member ? `状态 ${member.status}、岗位 ${member.岗位}` : '没有登记'}：不接受把复核结论记到一个不存在、不在岗、或不是复核员的名字上（Lead 代签面）。`,
      {
        requireAuthority: 'Lead',
        howToChange: '由 Lead 用 member_spawn 起一位复核员实例（岗位=复核员）并绑到「依赖本节点的复核任务」上，再由该实例自己发结论；历史代录只读，不迁移。',
        detail: { 复核者: 复核者id, 被复核节点 },
      },
    );
  }
  const 复核任务 = (await this.list({ 项目 })).filter(
    (n) => (n.依赖 ?? []).includes(被复核节点) && (n.绑定 ?? []).some((b) => String(b?.实例) === 复核者id),
  );
  if (复核任务.length === 0) {
    throw new Denied(
      '任务图 · 复核实例缺本任务关联（v2 条目11/8）',
      `复核者 ${复核者id} 没有被绑到任何「依赖 ${被复核节点} 的复核任务」上：没有真实关联的署名，只是一串名字。`,
      {
        requireAuthority: 'Lead',
        howToChange: `先建复核任务节点并把依赖写成本节点（依赖: ['${被复核节点}']），再 member_spawn 岗位=复核员 把实例绑上去；` +
          '复核实例绑的是它自己的复核节点，不改被复核节点的负责人。',
        detail: { 复核者: 复核者id, 被复核节点 },
      },
    );
  }
}

